UPDATE public.tours SET highlights = '[{"name":"Wasini Island","image_url":"/src/assets/place-wasini.jpg","description":"Dhow sail to Wasini for coral gardens, boardwalks and a Swahili seafood lunch."},{"name":"Kisite-Mpunguti Marine Park","image_url":"/src/assets/place-kisite-mpunguti.jpg","description":"Snorkel among coral reefs and swim with wild dolphins in a protected marine reserve."},{"name":"Sheldrick Falls","image_url":"/src/assets/place-sheldrick-falls.jpg","description":"Hike through Shimba Hills rainforest to a 25m waterfall and cool off in its natural pool."},{"name":"Kongo Mosque","image_url":"/src/assets/place-kongo-mosque.jpg","description":"Ancient coral-stone Swahili mosque ruins standing quietly on the white Diani shore."},{"name":"Mwaluganje Elephant Sanctuary","image_url":"/src/assets/place-mwaluganje-elephant.jpg","description":"Spot herds of African elephants roaming a community-run sanctuary in the coastal hills."},{"name":"Kaya Kinondo Sacred Forest","image_url":"/src/assets/place-kaya-kinondo.jpg","description":"Walk a centuries-old Mijikenda sacred grove of towering trees and hidden shrines."},{"name":"Shimoni Caves","image_url":"/src/assets/place-shimoni-caves.jpg","description":"Dark coral limestone sea caves with a sobering history of the East African slave trade."}]'::jsonb WHERE slug = 'diani-beach-escape';